function readOffset(rows, offset, limit){ return rows.slice(offset, offset+limit).map(r => r.id); }
let rows = [];
for (let i = 100; i >= 1; i--) rows.push({ id: i });
rows.sort((a,b) => b.id - a.id);
const page1 = readOffset(rows, 0, 3);
rows.unshift({ id: 101 });
const page2 = readOffset(rows, 3, 3);
const dup = page1.filter(id => page2.includes(id));
console.log('page1=' + JSON.stringify(page1));
console.log('page2=' + JSON.stringify(page2));
console.log(dup.length ? 'DRIFT id=' + dup.join(',') : 'STABLE');
